71	
72	    /**
73	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
74	     * domain containing at least one dot, with no whitespace in any part.
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
77	
78	    /**
79	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
80	     * new owner's id, customer code and registration date.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Common street-type abbreviations expanded during address normalization. Keys are the
86	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
87	     * expanded form it is replaced with.
88	     */
89	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
90	        "ST", "STREET",
91	        "RD", "ROAD",
92	        "AVE", "AVENUE");
93	
94	    /**
95	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
96	     * is at capacity and cannot take any more.
97	     */
98	    private static final int CITY_CAPACITY = 50;
99	
100	    /**
101	     * The maximum number of owners that may be registered in a single day. Once this many owners
102	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
103	     * owners can be created that day.
104	     */
105	    private static final int DAILY_OWNER_LIMIT = 100;
106	
107	    /**
108	     * The number of owners that may be registered on a single business day before a response starts
109	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
110	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
111	     * high volume.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    private final ClinicService clinicService;
116	
117	    private final OwnerMapper ownerMapper;
118	
119	    private final PetMapper petMapper;
120	
121	    private final VisitMapper visitMapper;
122	
123	    public OwnerRestControllerV1(ClinicService clinicService,
124	                                 OwnerMapper ownerMapper,
125	                                 PetMapper petMapper,
126	                                 VisitMapper visitMapper) {
127	        this.clinicService = clinicService;
128	        this.ownerMapper = ownerMapper;
129	        this.petMapper = petMapper;
130	        this.visitMapper = visitMapper;
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
136	        Collection<Owner> owners;
137	        if (lastName != null) {
138	            owners = this.clinicService.findOwnerByLastName(lastName);
139	        } else {
140	            owners = this.clinicService.findAllOwners();
141	        }
142	        if (owners.isEmpty()) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        applyBulkSignupWarning(ownerDto);
157	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
163	        validateRequiredFields(ownerFieldsDto);
164	        LocalDate registrationDate = toBusinessDay(
165	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
166	        rejectDailyLimitReached(registrationDate);
167	        HttpHeaders headers = new HttpHeaders();
168	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
169	        String address = normalizeAddress(ownerFieldsDto.getAddress());
170	        owner.setAddress(address);
171	        rejectCityAtCapacity(owner.getCity());
172	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
173	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
174	        } else {
175	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
176	        }
177	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
178	        rejectDuplicateTelephone(telephone);
179	        owner.setTelephone(telephone);
180	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
181	        owner.setRegistrationDate(registrationDate);
182	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
183	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
184	        this.clinicService.saveOwner(owner);
185	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
186	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
187	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
188	        applyBulkSignupWarning(ownerDto);
189	        headers.setLocation(UriComponentsBuilder.newInstance()
190	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
191	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
192	    }
