288	    /**
289	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
290	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
291	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
292	     *
293	     * @param ownerFieldsDto the submitted owner fields
294	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
295	     *                                     name of every offending field
296	     */
297	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
298	        List<String> missingFields = new ArrayList<>();
299	        if (isBlank(ownerFieldsDto.getFirstName())) {
300	            missingFields.add("firstName");
301	        }
302	        if (isBlank(ownerFieldsDto.getLastName())) {
303	            missingFields.add("lastName");
304	        }
305	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
306	            missingFields.add("address");
307	        }
308	        if (isBlank(ownerFieldsDto.getCity())) {
309	            missingFields.add("city");
310	        }
311	        if (isBlank(ownerFieldsDto.getTelephone())) {
312	            missingFields.add("telephone");
313	        }
314	        if (!missingFields.isEmpty()) {
315	            throw new InvalidOwnerFieldsException(missingFields);
316	        }
317	    }
318	
319	    private boolean isBlank(String value) {
320	        return value == null || value.isBlank();
321	    }
322	
323	    /**
324	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
325	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
326	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
327	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
328	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
329	     *
330	     * @param telephone the raw telephone value submitted by the client
331	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
332	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
333	     *                                     400 response
334	     */
335	    private String normalizeTelephone(String telephone) {
336	        String e164 = toE164(telephone);
337	        if (e164 == null) {
338	            throw new InvalidOwnerFieldsException(List.of("telephone"));
339	        }
340	        return e164;
341	    }
342	
343	    /**
344	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
345	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
346	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
347	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
348	     *
349	     * @param telephone the raw telephone value, possibly {@code null}
350	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
351	     */
352	    private String toE164(String telephone) {
353	        if (telephone == null) {
354	            return null;
355	        }
356	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
357	        boolean hasPlus = cleaned.startsWith("+");
358	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
359	        String nationalSignificant = hasPlus
360	            ? digits
361	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
362	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
363	            return null;
364	        }
365	        return "+" + nationalSignificant;
366	    }
367	
368	    /**
369	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
370	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
371	     * returned value is that address lower-cased.
372	     *
373	     * @param email the raw email value submitted by the client, or {@code null} if omitted
374	     * @return the lower-cased email, or {@code null} if none was supplied
375	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
376	     *                                     yielding a 400 response
377	     */
378	    private String normalizeEmail(String email) {
379	        if (email == null) {
380	            return null;
381	        }
382	        if (!EMAIL_PATTERN.matcher(email).matches()) {
383	            throw new InvalidOwnerFieldsException(List.of("email"));
384	        }
385	        return email.toLowerCase(Locale.ROOT);
386	    }
387	
388	    /**
389	     * Counts the existing owners that, before this create, already share the given first name and
390	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
391	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
392	     * been saved yet, so it is never included in the count.
393	     *
394	     * @param firstName the first name of the owner being created
395	     * @param lastName  the last name of the owner being created
396	     * @return the number of existing owners sharing both names
397	     */
398	    private int countNamesakes(String firstName, String lastName) {
399	        String normalizedFirstName = normalizeForComparison(firstName);
400	        String normalizedLastName = normalizeForComparison(lastName);
401	        return (int) this.clinicService.findAllOwners().stream()
402	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
403	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
404	            .count();
405	    }
406	
407	    /**
408	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
409	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
410	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
411	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
412	     *
413	     * @param city     the owner's city
414	     * @param lastName the owner's last name
415	     * @return the formatted customer code
416	     */
417	    private String generateCustomerCode(String city, String lastName) {
418	        String city3 = first3Letters(city);
419	        String last3 = first3Letters(lastName);
420	        int sequence = countOwnersInCity(city) + 1;
421	        return String.format("%s-%s-%04d", city3, last3, sequence);
422	    }
423	
424	    /**
425	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
426	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
427	     *
428	     * @param value the value to abbreviate
429	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
430	     */
431	    private String first3Letters(String value) {
432	        String letters = value.replaceAll("[^\\p{L}]", "");
433	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
434	    }
435	
436	    /**
437	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
438	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
439	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
440	     * has not been saved yet, so it is never included in the count.
441	     *
442	     * @param city the city of the owner being created
443	     * @return the number of existing owners in that city
444	     */
445	    private int countOwnersInCity(String city) {
446	        String normalizedCity = normalizeForComparison(city);
447	        return (int) this.clinicService.findAllOwners().stream()
448	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
449	            .count();
450	    }
451	
452	    /**
453	     * Rejects creation of an owner whose city already contains the maximum number of owners
454	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
455	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
456	     *
457	     * @param city the city of the owner being created
458	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
459	     *                                      owners, yielding a 409 Conflict response
460	     */
461	    private void rejectCityAtCapacity(String city) {
462	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
463	            throw new OwnerCityAtCapacityException(city);
464	        }
465	    }
466	
467	    /**
468	     * Rejects creation of an owner once the given business day has already reached its daily quota
469	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
470	     * being that day — the adjusted business day the owner being created will carry — so the quota
471	     * applies per business day. The owner being created has not been saved yet, so it is never
472	     * included in the count.
473	     *
474	     * @param registrationDate the adjusted business-day registration date of the owner being created
475	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
476	     *                                         carry that registration date, yielding a
477	     *                                         429 Too Many Requests response
478	     */
479	    private void rejectDailyLimitReached(LocalDate registrationDate) {
480	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
481	            throw new DailyOwnerLimitReachedException(registrationDate);
482	        }
483	    }
484	
485	    /**
486	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
487	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
488	     *
489	     * @param registrationDate the business day to count owners for
490	     * @return the number of existing owners registered on that day
491	     */
492	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
493	        return this.clinicService.findAllOwners().stream()
494	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
495	            .count();
496	    }
497	
498	    /**
499	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
500	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
501	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
502	     * otherwise.
503	     *
504	     * @param ownerDto the owner response to flag
505	     */
506	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
507	        LocalDate today = toBusinessDay(LocalDate.now());
508	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
509	    }
510	
511	    /**
512	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
513	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
514	     * applies to the effective registration date whether it was supplied in the request or defaulted
515	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
516	     * feeds every value derived from it (such as the membership number's year segment and the daily
517	     * create-limit's per-day bucket).
518	     *
519	     * @param date the effective registration date, supplied or defaulted
520	     * @return the same date when it is a weekday, otherwise the next Monday
521	     */
522	    private LocalDate toBusinessDay(LocalDate date) {
523	        LocalDate adjusted = date;
524	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
525	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
526	            adjusted = adjusted.plusDays(1);
527	        }
528	        return adjusted;
529	    }
530	
531	    /**
532	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
533	     * telephones are converted to E.164 here as well so the comparison is independent of the format
534	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
535	     * ignored rather than matched.
536	     *
537	     * @param telephone the E.164 telephone of the owner being created
538	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
539	     *                                          yielding a 409 Conflict response
540	     */
541	    private void rejectDuplicateTelephone(String telephone) {
542	        boolean inUse = this.clinicService.findAllOwners().stream()
543	            .map(Owner::getTelephone)
544	            .map(this::toE164)
545	            .anyMatch(telephone::equals);
546	        if (inUse) {
547	            throw new DuplicateOwnerTelephoneException(telephone);
548	        }
549	    }
550	
551	    /**
552	     * Rejects creation of an owner whose last name and address both match an existing owner's,
553	     * which marks them as belonging to the same household. Both the last name and the address are
554	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
555	     * that differ only in letter case or spacing are still treated as a match.
556	     *
557	     * @param lastName the last name of the owner being created
558	     * @param address  the address of the owner being created
559	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
560	     *                                          address, yielding a 409 Conflict response
561	     */
562	    private void rejectDuplicateHousehold(String lastName, String address) {
563	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
564	            throw new DuplicateOwnerHouseholdException(lastName, address);
565	        }
566	    }
567	
568	    /**
569	     * Finds every existing owner belonging to the household identified by the given last name and
570	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
571	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
572	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
573	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
574	     * and {@link #assignHousehold}.
575	     *
576	     * @param lastName the last name of the owner being created
577	     * @param address  the address of the owner being created
578	     * @return the existing owners in that household, or an empty list if there are none
579	     */
580	    private List<Owner> findHouseholdMembers(String lastName, String address) {
581	        String normalizedLastName = normalizeForComparison(lastName);
582	        String normalizedAddress = normalizeAddress(address);
583	        return this.clinicService.findAllOwners().stream()
584	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
585	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
586	            .toList();
587	    }
588	
589	    /**
590	     * Enrolls a newly created owner into the household of any existing owner that shares its last
591	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
592	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
593	     * whitespace. When at least one such owner already exists, every member of the household — the
594	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
595	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
596	     * and address is created and back-filled onto the existing members. When no owner yet lives at
597	     * that address under the same last name no identifier is assigned and the owner is created alone.
598	     *
599	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
600	     * @param lastName the last name of the owner being created
601	     * @param address  the address of the owner being created
602	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
603	     */
604	    private String assignHousehold(Owner newOwner, String lastName, String address) {
605	        List<Owner> members = findHouseholdMembers(lastName, address);
606	        if (members.isEmpty()) {
607	            return null;
608	        }
609	        String householdId = members.stream()
610	            .map(Owner::getHouseholdId)
611	            .filter(existing -> existing != null && !existing.isBlank())
612	            .findFirst()
613	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
614	        for (Owner member : members) {
615	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
616	                member.setHouseholdId(householdId);
617	                this.clinicService.saveOwner(member);
618	            }
619	        }
620	        newOwner.setHouseholdId(householdId);
621	        return householdId;
622	    }
623	
624	    /**
625	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
626	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
627	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
628	     * same identifier, so members of one household share a single value.
629	     *
630	     * @param normalizedLastName the household's last name, already normalized for comparison
631	     * @param normalizedAddress  the household's address, already normalized for comparison
632	     * @return the derived household identifier
633	     */
634	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
635	        try {
636	            byte[] digest = MessageDigest.getInstance("SHA-256")
637	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
638	            StringBuilder hex = new StringBuilder(digest.length * 2);
639	            for (byte b : digest) {
640	                hex.append(String.format("%02x", b));
641	            }
642	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
643	        } catch (NoSuchAlgorithmException e) {
644	            throw new IllegalStateException("SHA-256 algorithm not available", e);
645	        }
646	    }
647	
648	    /**
649	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
650	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
651	     * the result is lower-cased.
652	     *
653	     * @param value the value to normalize, possibly {@code null}
654	     * @return the normalized value, or an empty string if {@code value} is {@code null}
655	     */
656	    private String normalizeForComparison(String value) {
657	        if (value == null) {
658	            return "";
659	        }
660	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
661	    }
662	
663	    /**
664	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
665	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
666	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
667	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
668	     * This normalized value is what gets stored and returned, and it is the form every address
669	     * comparison (household duplicate detection and the shared household id) uses.
670	     *
671	     * @param address the raw address value submitted by the client, possibly {@code null}
672	     * @return the normalized address, or an empty string if {@code address} is {@code null}
673	     */
674	    private String normalizeAddress(String address) {
675	        if (address == null) {
676	            return "";
677	        }
678	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
679	        if (collapsed.isEmpty()) {
680	            return collapsed;
681	        }
682	        String[] tokens = collapsed.split(" ");
683	        StringBuilder normalized = new StringBuilder(collapsed.length());
684	        for (int i = 0; i < tokens.length; i++) {
685	            if (i > 0) {
686	                normalized.append(' ');
687	            }
688	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
689	        }
690	        return normalized.toString();
691	    }
692	}
